local FishingBoatMaker = {}
local PRODUCTS = {
    simple_wood_fishing_boat = { name = "Preprost leseni ribiški čoln", woodCost = 6, ropeCost = 2, time = 8, cost = 300, food = 30, happiness = 2, description = "Preprost leseni ribiški čoln za obalni ribolov." },
    oak_hulled_fishing_boat = { name = "Hrastovotrupni ribiški čoln", woodCost = 6, ironCost = 2, ropeCost = 2, time = 11, cost = 680, food = 45, happiness = 2, prestige = 2, description = "Hrastovotrupni ribiški čoln za trgovce." },
    silver_fitted_boat = { name = "Srebrnoopremljeni ribiški čoln", woodCost = 6, silverCost = 1, ironCost = 2, ropeCost = 2, time = 15, cost = 1500, food = 60, happiness = 3, prestige = 6, description = "Srebrnoopremljeni ribiški čoln za plemiče." },
    gold_trimmed_boat = { name = "Zlatookrasni ribiški čoln", woodCost = 6, goldCost = 1, silverCost = 1, ironCost = 2, ropeCost = 2, time = 19, cost = 3400, food = 78, happiness = 4, prestige = 14, description = "Zlatookrasni ribiški čoln za visoke plemiče." },
    jewel_figured_boat = { name = "Draguljasta ribiški čoln", woodCost = 6, goldCost = 1, silverCost = 1, ironCost = 2, ropeCost = 2, jewelCost = 1, time = 23, cost = 7200, food = 95, happiness = 6, prestige = 27, description = "Ribiški čoln z draguljem za visoko plemstvo." },
    royal_grand_fishing_boat = { name = "Kraljevski veliki ribiški čoln", woodCost = 8, goldCost = 2, silverCost = 2, ironCost = 2, ropeCost = 2, jewelCost = 2, pearlCost = 2, time = 30, cost = 15000, food = 110, happiness = 13, prestige = 58, description = "Veliki kraljevski ribiški čoln z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    boat_workshop = { name = "Čolnarska delavnica", cost = { gold = 320, wood = 200, stone = 160, rope = 6, iron = 4 }, upkeep = 7, qualityBonus = 5 },
    shipyard_loft = { name = "Ladjedelska podstrešje", cost = { gold = 1200, wood = 360, stone = 320, silver = 6, iron = 8 }, upkeep = 28, qualityBonus = 18 },
    master_boatbuilder_atelier = { name = "Mojstrski čolnarski atelje", cost = { gold = 3000, wood = 400, stone = 520, silver = 32, gold = 6 }, upkeep = 70, qualityBonus = 30 },
    royal_shipyard_palace = { name = "Kraljevska ladjedelska palača", cost = { gold = 13000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
FishingBoatMaker.woodStock = 24; FishingBoatMaker.ironStock = 12; FishingBoatMaker.ropeStock = 12; FishingBoatMaker.silverStock = 6; FishingBoatMaker.goldStock = 6; FishingBoatMaker.jewelStock = 4; FishingBoatMaker.pearlStock = 4
FishingBoatMaker.productStock = {}; FishingBoatMaker.buildings = {}; FishingBoatMaker.maker = nil; FishingBoatMaker.activeMaking = {}; FishingBoatMaker.totalProducts = 0; FishingBoatMaker.dayTimer = 0
function FishingBoatMaker.init() FishingBoatMaker.woodStock=24; FishingBoatMaker.ironStock=12; FishingBoatMaker.ropeStock=12; FishingBoatMaker.silverStock=6; FishingBoatMaker.goldStock=6; FishingBoatMaker.jewelStock=4; FishingBoatMaker.pearlStock=4; FishingBoatMaker.productStock={}; FishingBoatMaker.buildings={}; FishingBoatMaker.maker=nil; FishingBoatMaker.activeMaking={}; FishingBoatMaker.totalProducts=0; FishingBoatMaker.dayTimer=0; print("[FishingBoatMaker] Royal Fishing Boat Maker System initialized (6 products, 4 buildings)") end
function FishingBoatMaker.hireMaker(n,s) s=s or math.random(55,90); local c=640+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FishingBoatMaker.maker={name=n or ("Čolnar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čolnar najet: %s (spretnost: %d)",FishingBoatMaker.maker.name,s),"success") end; return true end
function FishingBoatMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FishingBoatMaker.build(id) local ok,e=FishingBoatMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FishingBoatMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FishingBoatMaker.getQualityBonus() local b=0; for _,bd in ipairs(FishingBoatMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FishingBoatMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and FishingBoatMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and FishingBoatMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.ropeCost and FishingBoatMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and FishingBoatMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FishingBoatMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FishingBoatMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FishingBoatMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FishingBoatMaker.buildings==0 then return false,"Potrebna čolnarska delavnica" end; if not FishingBoatMaker.maker then return false,"Potreben čolnar" end; return true end
function FishingBoatMaker.make(pt,qty) qty=qty or 1; local ok,e=FishingBoatMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then FishingBoatMaker.woodStock=FishingBoatMaker.woodStock-d.woodCost*qty end; if d.ironCost then FishingBoatMaker.ironStock=FishingBoatMaker.ironStock-d.ironCost*qty end; if d.ropeCost then FishingBoatMaker.ropeStock=FishingBoatMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then FishingBoatMaker.silverStock=FishingBoatMaker.silverStock-d.silverCost*qty end; if d.goldCost then FishingBoatMaker.goldStock=FishingBoatMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FishingBoatMaker.jewelStock=FishingBoatMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FishingBoatMaker.pearlStock=FishingBoatMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FishingBoatMaker.maker then t=math.max(1,t-math.floor(FishingBoatMaker.maker.skill/12)) end; table.insert(FishingBoatMaker.activeMaking,{id="fishingboat_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gradnja: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FishingBoatMaker.completeMaking(m) local q=1.0+(FishingBoatMaker.getQualityBonus()/100); if FishingBoatMaker.maker then q=q+(FishingBoatMaker.maker.skill/140) end; q=math.min(2.5,q); FishingBoatMaker.productStock[m.productType]=(FishingBoatMaker.productStock[m.productType] or 0)+m.quantity; FishingBoatMaker.totalProducts=FishingBoatMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FishingBoatMaker.maker then FishingBoatMaker.maker.itemsMade=FishingBoatMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FishingBoatMaker.maker.skill=math.min(100,FishingBoatMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ribiški čoln izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fishingboat.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function FishingBoatMaker.update(dt) if not _G.state then return end; FishingBoatMaker.dayTimer=FishingBoatMaker.dayTimer+dt; if FishingBoatMaker.dayTimer>=30 then FishingBoatMaker.dayTimer=0; for i=#FishingBoatMaker.activeMaking,1,-1 do local m=FishingBoatMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FishingBoatMaker.completeMaking(m); table.remove(FishingBoatMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FishingBoatMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FishingBoatMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FishingBoatMaker.getStats() return {woodStock=FishingBoatMaker.woodStock,ironStock=FishingBoatMaker.ironStock,ropeStock=FishingBoatMaker.ropeStock,silverStock=FishingBoatMaker.silverStock,goldStock=FishingBoatMaker.goldStock,jewelStock=FishingBoatMaker.jewelStock,pearlStock=FishingBoatMaker.pearlStock,productStock=FishingBoatMaker.productStock,numBuildings=#FishingBoatMaker.buildings,hasMaker=FishingBoatMaker.maker~=nil,makerName=FishingBoatMaker.maker and FishingBoatMaker.maker.name or "—",makerSkill=FishingBoatMaker.maker and FishingBoatMaker.maker.skill or 0,activeMaking=#FishingBoatMaker.activeMaking,totalProducts=FishingBoatMaker.totalProducts} end
return FishingBoatMaker
